+package httpapi
+
+import (
+	"testing"
+)
+
+func TestGenerateState_Length(t *testing.T) {
+	state, err := generateState()
+	if err != nil {
+		t.Fatalf("generateState: %v", err)
+	}
+	// base64url of 32 bytes = 44 chars (with padding)
+	if len(state) < 40 {
+		t.Fatalf("state too short: %d chars", len(state))
+	}
+}
+
+func TestGenerateState_Uniqueness(t *testing.T) {
+	const N = 100
+	seen := make(map[string]bool, N)
+	for i := 0; i < N; i++ {
+		s, err := generateState()
+		if err != nil {
+			t.Fatalf("generateState[%d]: %v", i, err)
+		}
+		if seen[s] {
+			t.Fatalf("duplicate state generated at iteration %d", i)
+		}
+		seen[s] = true
+	}
+}
+
+func TestGenerateState_OnlyURLSafeChars(t *testing.T) {
+	state, err := generateState()
+	if err != nil {
+		t.Fatalf("generateState: %v", err)
+	}
+	// base64url alphabet + padding
+	for _, ch := range state {
+		if !isBase64URLChar(ch) {
+			t.Fatalf("non-base64url character %q in state %q", ch, state)
+		}
+	}
+}
+
+func isBase64URLChar(r rune) bool {
+	return (r >= 'A' && r <= 'Z') ||
+		(r >= 'a' && r <= 'z') ||
+		(r >= '0' && r <= '9') ||
+		r == '-' || r == '_' || r == '='
+}
